import type { CSSProperties } from 'react';

/**
 * SF Symbol rendered as a CSS mask so it takes the current text colour.
 * PNGs live in public/sf and are generated by scripts/render-sf-symbols.swift.
 */
export default function Icon({ name, size, className = '', style }: { name: string; size?: number; className?: string; style?: CSSProperties }) {
  return (
    <span
      aria-hidden="true"
      className={`sf ${className}`}
      style={{
        WebkitMaskImage: `url(/sf/${name}.png)`,
        maskImage: `url(/sf/${name}.png)`,
        ...(size ? { width: size, height: size } : null),
        ...style
      }}
    />
  );
}
